import React, { useEffect, useState } from 'react';
import { Box, IconButton, Stack, Typography, Button, Divider, Tooltip } from '@mui/material';
import { ArchiveBox, CircleDashed, MagnifyingGlass, UserPlus } from 'phosphor-react';
import { useTheme } from '@mui/material/styles';
import { Search, SearchIconWrapper, StyledInputBase } from '../../components/Search';
import ChatElement from '../../components/ChatElement';
import styled from 'styled-components';
import Friends from '../../sections/main/Friends';
import { useDispatch, useSelector } from 'react-redux';
import { SelectConversation } from '../../redux/slices/app';
import webSocketService from '../../webSocketService';
import { FetchDirectConversations } from '../../redux/slices/conversation';
import useResponsive from "../../hooks/useResponsive";
import BottomNav from "../../layouts/dashboard/BottomNav";
import ScrollbarStyles from '../../components/ScrollBarStyles';


const Chats = () => {

  const user_id = window.localStorage.getItem("user_id");
  const isDesktop = useResponsive("up", "md");
  const [openDialog, setOpenDialog] = useState(false);

  const { conversations } = useSelector((state) => state.conversation.direct_chat);
  const { token } = useSelector((state) => state.auth);

  useEffect(() => {
    dispatch(FetchDirectConversations());
  }, [])

  const handleOpenDialog = () => {
    setOpenDialog(true);
  }
  const handleCloseDialog = () => {
    setOpenDialog(false);
  }

  const dispatch = useDispatch();

  const theme = useTheme();


  return (
    <>
      <Box
        zIndex={3}
        sx={{
          position: "relative",
          height: "100%",
          width: isDesktop ? 320 : "100vw",
          backgroundColor: theme.palette.mode === "light" ? "#F8FAFF" : theme.palette.background,
          boxShadow: "0px 0px 2px rgba(0, 0, 0, 0.25)",
        }}
      >
        {!isDesktop && (
          // Bottom Nav
          <BottomNav />
        )}

        <Stack spacing={2} sx={{ maxHeight: "100vh" }}>
          {/* Header */}
          <Stack
            px={3}
            pt={3}
            alignItems={"center"}
            justifyContent="space-between"
            direction="row"
          >
            <Typography variant="h5">Chats</Typography>

            <Stack position={"absolute"} right={1} direction={"row"} alignItems="center" spacing={1}>
              <Tooltip placement='right' title={"Start a new conversation"}>
                <IconButton
                  onClick={() => {
                    handleOpenDialog();
                  }}
                  sx={{ width: "max-content" }}
                >
                  <UserPlus />
                </IconButton>
              </Tooltip>
              <IconButton sx={{ width: "max-content" }}>
                <CircleDashed />
              </IconButton>
            </Stack>
          </Stack>
          {/* Search */}
          <Stack px={3} sx={{ width: "100%" }}>
            <Search>
              <SearchIconWrapper>
                <MagnifyingGlass color="#709CE6" />
              </SearchIconWrapper>
              <StyledInputBase
                placeholder="Search…"
                inputProps={{ "aria-label": "search" }}
              />
            </Search>
          </Stack>
          {/* Archive */}
          <Stack px={3} pt={0.5}>
            <Stack direction={"row"} spacing={1.5} alignItems="center">
              <ArchiveBox size={25} />
              <Button variant="text">Archive</Button>
            </Stack>
          </Stack>
          <Stack px={3}>
            <Divider />
          </Stack>
          <Stack px={2} pl={2.5} pb={2} sx={{ flexGrow: 1, overflowY: "scroll", height: "100%" }}>
            <ScrollbarStyles />
            <Stack spacing={2.4}>
              {/* <Typography variant="subtitle2" sx={{ color: "#676667" }}>
                Pinned
              </Typography> */}
              {/* {conversations.filter((el) => el.pinned).map((el, idx) => {
                return <ChatElement {...el} />;
              })} */}
              <Typography variant="subtitle2" sx={{ color: "#676667" }}>
                All Chats
              </Typography>
              {conversations.filter((el) => !el.pinned).map((el, idx) => {
                return <ChatElement {...el} />;
              })}
            </Stack>
          </Stack>
        </Stack>
      </Box>
      {openDialog && (
        <Friends open={openDialog} handleClose={handleCloseDialog} />
      )}
    </>
  );
};


export default Chats